const actions={save_campaign:{slug:'founding-fund',title:'AfriRise founding fund',goal_cents:50000000,currency:'USD',status:'draft',accepting_donations:true,activities:'',beneficiaries:'',location:'',eligibility:'',selection_process:'',budget:'',timeline:'',underfunding:'',excess_funds:'',delivery_impossible:'',update_schedule:'',refunds:'',cancellation:'',privacy:'',safeguarding:'',complaints:'',support_email:'',terms_version:'draft-1'},submit_expense:{campaign_id:'',description:'',amount_cents:0},approve_expense:{id:''},record_reconciliation:{payment_id:'',bank_reference:'',bank_received_cents:0,note:''},record_refund:{payment_id:'',refunded_cents:0,provider_refund_reference:''},save_milestone:{campaign_id:'',title:'',description:'',due_date:'',outcome:''},submit_content:{campaign_id:'',title:'',body:'',consent_reference:''},approve_content:{id:''}};
