async function responseData(response){const text=await response.text();if(!text)return null;try{return JSON.parse(text)}catch{return {error:text.slice(0,180)}}}async function auth(path,method='GET',body){const r=await fetch(cfg.supabaseUrl+'/auth/v1/'+path,{method,headers:{apikey:cfg.supabaseAnonKey,'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},...(body&&{body:JSON.stringify(body)})}),d=await responseData(r);if(!r.ok)throw Error(d?.msg||d?.message||d?.error_description||`Authentication failed (${r.status}).`);return d}async function api(path,body){const r=await fetch(cfg.apiBase+path,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'},...(body&&{body:JSON.stringify(body)})}),d=await responseData(r);if(!r.ok)throw Error(d?.error||`Operational API is unavailable (${r.status}). Deploy afririse-api and check SITE_ORIGIN.`);return d}
if(cfg.apiBase&&cfg.supabaseUrl&&cfg.supabaseAnonKey){document.querySelector('#login-button').disabled=false;status.textContent='Staff sign-in requires an assigned role and authenticator verification.'}
function startWorkspace(staffRole,message){role=staffRole;loginPanel.hidden=true;adminWorkspace.hidden=false;status.textContent=message;controls();Promise.all([loadDashboard(),loadRecords()])}
document.querySelector('#login-form').addEventListener('submit',async e=>{e.preventDefault();try{const r=await auth('token?grant_type=password','POST',{email:adminEmail.value,password:adminPassword.value});token=r.access_token;adminPassword.value='';loginForm.hidden=true;logout.hidden=false;const f=await auth('factors'),list=Array.isArray(f)?f:(f.all||f.totp||[]),verified=list.find(x=>x.factor_type==='totp'&&x.status==='verified');mfaPanel.hidden=false;if(verified){factorId=verified.id;mfaInfo.textContent='Enter the code from your authenticator app.'}else{const created=await auth('factors','POST',{factor_type:'totp',friendly_name:'AfriRise staff'});factorId=created.id;mfaInfo.textContent='Add this setup secret to your authenticator: '+created.totp.secret;status.textContent='Finish MFA enrolment to access operational records.'}}catch(e){status.textContent=e.message}});
document.querySelector('#mfa-form').addEventListener('submit',async e=>{e.preventDefault();try{const c=await auth(`factors/${factorId}/challenge`,'POST',{}),v=await auth(`factors/${factorId}/verify`,'POST',{challenge_id:c.id,code:mfaCode.value});token=v.access_token;mfaCode.value='';const session=await api('/admin/session');startWorkspace(session.role,`Signed in · ${session.role} · MFA verified`)}catch(e){status.textContent=e.message}});
function controls(){adminNav.replaceChildren();for(const name of resources[role]){const b=document.createElement('button');b.textContent=label(name);b.onclick=()=>{resource=name;offset=0;loadRecords()};adminNav.append(b)}adminAction.replaceChildren();for(const action of allowed[role])adminAction.add(new Option(label(action),action));template()}function template(){actionData.value=JSON.stringify(actions[adminAction.value],null,2)}adminAction.onchange=template;
function metric(title,value,detail,kind=''){const el=document.createElement('article');el.className='metric-card '+kind;el.innerHTML=`<span>${title}</span><strong>${value}</strong><small>${detail}</small>`;return el}function renderDashboard(data){const m=data.metrics;dashboardMetrics.replaceChildren();const cards=role==='editor'?[['Campaigns',m.campaigns||0,`${m.liveCampaigns||0} live`],['Open support',m.openSupport||0,'Requests needing response']]:[['Net collection',money(m.netCents),'After fees and refunds','featured'],['Paid payments',m.paidPayments||0,`${m.pendingIntents||0} awaiting payment`],['Live campaigns',m.liveCampaigns||0,`${m.campaigns||0} total campaigns`],['Open support',m.openSupport||0,'Requests needing response'],['Webhook review',m.webhookReview||0,'Provider events requiring review']];cards.forEach(x=>dashboardMetrics.append(metric(...x)));revenueTotal.textContent=money(m.netCents);revenueChart.replaceChildren();const max=Math.max(1,...data.revenue.map(x=>x.cents));data.revenue.forEach(x=>{const el=document.createElement('div');el.className='chart-column';el.innerHTML=`<span class="chart-value">${money(x.cents)}</span><i style="height:${Math.max(4,Math.round(x.cents/max*100))}%"></i><small>${new Date(x.date+'T00:00:00Z').toLocaleDateString('en-US',{weekday:'short'})}</small>`;revenueChart.append(el)});attentionQueue.replaceChildren();[['Webhook events',m.webhookReview||0,'Require payment-provider review'],['Donation intents',m.reviewIntents||0,'Flagged for review'],['Expense approvals',m.openExpenses||0,'Awaiting a separate approver'],['Support requests',m.openSupport||0,'Open visitor requests']].forEach(x=>{const el=document.createElement('div');el.className='queue-row';el.innerHTML=`<span><strong>${x[0]}</strong><small>${x[2]}</small></span><b class="${x[1]?'attention-count':''}">${x[1]}</b>`;attentionQueue.append(el)});activityFeed.replaceChildren();if(!data.activity.length)activityFeed.innerHTML='<p class="micro">No recorded operational activity yet.</p>';data.activity.forEach(x=>{const el=document.createElement('article');el.className='activity-row';el.innerHTML=`<i class="activity-dot ${x.kind}"></i><div><strong>${label(x.title)}</strong><p>${x.detail}</p></div><time datetime="${x.at}">${when(x.at)}</time>`;activityFeed.append(el)})}async function loadDashboard(){try{refreshDashboard.disabled=true;renderDashboard(await api('/admin/dashboard'))}catch(e){status.textContent=e.message}finally{refreshDashboard.disabled=false}}
async function loadRecords(){try{const rows=await api(`/admin/records?resource=${resource}&offset=${offset}`),cols=rows.length?Object.keys(rows[0]):[];recordsTitle.textContent=label(resource);recordsHead.replaceChildren();recordsBody.replaceChildren();const head=document.createElement('tr');cols.forEach(key=>{const th=document.createElement('th');th.textContent=label(key);head.append(th)});recordsHead.append(head);rows.forEach(row=>{const tr=document.createElement('tr');cols.forEach(key=>{const td=document.createElement('td');td.textContent=typeof row[key]==='object'?JSON.stringify(row[key]):String(row[key]??'');tr.append(td)});recordsBody.append(tr)});if(!rows.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=Math.max(cols.length,1);td.textContent='No records on this page.';tr.append(td);recordsBody.append(tr)}previousPage.disabled=!offset;nextPage.disabled=rows.length<100;[...adminNav.children].forEach(b=>b.classList.toggle('active',b.textContent===label(resource)))}catch(e){status.textContent=e.message}}
saveAction.onclick=async()=>{try{const data=JSON.parse(actionData.value);await api('/admin/action',{action:adminAction.value,data});actionFeedback.textContent='Saved with an audit record.';await Promise.all([loadRecords(),loadDashboard()])}catch(e){actionFeedback.textContent=e.message}};refreshDashboard.onclick=loadDashboard;previousPage.onclick=()=>{offset=Math.max(0,offset-100);loadRecords()};nextPage.onclick=()=>{offset+=100;loadRecords()};logout.onclick=async()=>{try{await auth('logout','POST',{})}catch{}token=null;location.reload()};
